-- Reescritura completa de la secuencia Oportunidad (v2)
-- Más humana, párrafos cortos, storytelling, botón de WhatsApp en los 8, y de
-- 2 a 4 imágenes por correo. El correo 1 ya no supone nada de la operación del
-- lead: enumera lo que resolvemos que un genérico no. Se agrega el correo de
-- las marcas que ponen el ejemplo (Bershka / WOW Concept).
begin;
delete from crm_secuencia_pasos where secuencia_id in (select id from crm_secuencias where nombre = 'Oportunidad · Moda multitienda');
delete from email_templates where nombre like 'Oportunidad %';

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Oportunidad 1 · Diez cosas que un genérico no hace', 'Diez cosas que un sistema genérico no hace', 'Ninguna es una función bonita. Las diez son plata que se queda en el piso.', 'automatizado', 'simple', 'ventas',
        '[{"id":"t1","tipo":"texto","texto":"{{nombre|Hola}}, gracias por el tiempo de la demo."},{"id":"t2","tipo":"texto","texto":"No te voy a repetir lo que ya viste."},{"id":"t3","tipo":"texto","texto":"Te voy a decir algo distinto: **por qué un sistema hecho para vender ropa no se parece a uno hecho para vender cualquier cosa.**"},{"id":"t4","tipo":"texto","texto":"Casi todos los sistemas del mercado tratan una blusa como si fuera un martillo. Un producto, un código, un número.\n\nPero tú no vendes «una blusa». 👗"},{"id":"i1","tipo":"imagen","src":"https://www.sacscloud.com/email/moda/moda-matriz.png","alt":"Matriz de tallas y colores con siete celdas en cero","pie":"Seis tallas en cuatro colores. Veinticuatro piezas distintas que comprar, guardar y contar — de un solo modelo."},{"id":"t5","tipo":"texto","texto":"Vendes seis tallas en cuatro colores. Veinticuatro cosas distintas.\n\nY las que están en cero son, casi siempre, las que te están pidiendo."},{"id":"s1","tipo":"separador"},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Las diez"},{"id":"l1","tipo":"lista","items":["🧵 **La prenda es talla × color, no un código.** No un producto por cada combinación, ni un solo producto que no sabe qué talla le queda.","📉 **La talla agotada no cuenta como talla muerta.** Si la M se acabó el día 9, el sistema lo sabe. No la anota como «no gustó».","🏬 **Existencia por talla en cada tienda.** No un total de la cadena que no te sirve para contestarle a la clienta que tienes enfrente.","🔁 **El traspaso se propone solo.** Ve el hueco de una tienda y el excedente de otra, y te dice qué mover — con su documento.","🎨 **Salud de corrida por color.** Qué colores están completos, cuáles se rompieron y cuáles nunca debieron comprarse.","📐 **Curva objetivo por categoría.** Tú defines cómo se compra una blusa y cómo se compra un pantalón. No una regla para todo.","🥾 **La talla 22.5 se ordena como número.** Suena a nada. Pregúntale a quien vende calzado cuántos años lleva peleando con ese reporte.","🛍️ **Apartados con su saldo.** Vivos en el sistema, no en una libreta bajo el mostrador.","🌐 **Un solo inventario** para el piso, la tienda en línea y el WhatsApp. Sin vender dos veces la misma talla.","💵 **Precio por plaza.** Porque Polanco no es Satélite, y tu sistema debería saberlo."]},{"id":"s2","tipo":"separador"},{"id":"h2","tipo":"encabezado","nivel":2,"texto":"Y esto no es teoría"},{"id":"t6","tipo":"texto","texto":"LiveShow vende merch de giras en México: playeras y hoodies con tallas, en cientos de puntos de venta a la vez. Shakira, Metallica, Karol G."},{"id":"m1","tipo":"metricas","items":[{"cifra":"150,000+","texto":"transacciones sin un error"},{"cifra":"4 / min","texto":"ventas en hora pico"},{"cifra":"+15%","texto":"ticket promedio"}]},{"id":"c1","tipo":"cita","texto":"En un concierto perdimos 20% de ventas en dos horas porque el sistema colapsó. Con SACS eso no vuelve a pasar.","autor":"Mariana López · Directora de Operaciones, LiveShow"},{"id":"t7","tipo":"texto","texto":"En un evento no hay resurtido: lo que llegó es todo lo que habrá.\n\nEs tu temporada, comprimida en ocho horas."},{"id":"b1","tipo":"boton","texto":"💬 Escríbeme por WhatsApp","align":"center","sub":"¿Alguna de las diez te suena a tu operación? Cuéntame cuál.","href":"https://wa.me/12058920417?text=Hola%20Andrea,%20vi%20el%20correo%20de%20las%20diez%20cosas%20y%20quiero%20preguntarte%20una"},{"id":"fi","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"},{"id":"pd","tipo":"texto","texto":"P.D. Si de las diez solo te pegan dos, esas dos son por donde hay que empezar. No hay que comprarlo todo el mismo día — hay que arrancar en el orden correcto."}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Oportunidad 2 · Las 7 preguntas', 'Las 7 preguntas antes de firmar un sistema', 'Y cómo las contestamos nosotros, una por una.', 'automatizado', 'simple', 'ventas',
        '[{"id":"t1","tipo":"texto","texto":"{{nombre|Hola}}, si estás comparando sistemas, esto te va a ahorrar semanas."},{"id":"t2","tipo":"texto","texto":"Son las siete preguntas que yo haría si vendiera ropa en más de una tienda."},{"id":"t3","tipo":"texto","texto":"Y debajo de cada una, **cómo la contesta Sacs.** Sin rodeos."},{"id":"i1","tipo":"imagen","src":"https://www.sacscloud.com/email/moda/moda-hoja-linea.jpg","alt":"Hoja de línea impresa con la corrida de tallas, un lápiz y una tarjeta de swatches","pie":"La hoja de línea: donde de verdad se decide la temporada."},{"id":"s1","tipo":"separador"},{"id":"h1","tipo":"encabezado","nivel":3,"texto":"1 · Cuando una talla se agota, ¿el sistema lo sabe?"},{"id":"q1","tipo":"texto","texto":"¿O solo ve que dejó de venderse?\n\nEs la diferencia entre «la M no gustó» y «la M se acabó el día 9»."},{"id":"a1","tipo":"aviso","texto":"✅ **Sacs lo sabe.** Detecta que la talla estuvo agotada y estima lo que habría vendido, con cinco métodos que tú eliges."},{"id":"h2","tipo":"encabezado","nivel":3,"texto":"2 · ¿Puedo ver con qué criterio calculó la corrida?"},{"id":"q2","tipo":"texto","texto":"Pide la fórmula. Si te dicen «es un algoritmo», es una caja negra — y tú firmas la orden de compra."},{"id":"a2","tipo":"aviso","texto":"✅ **Sacs te enseña el criterio y te deja cambiarlo.** Promedio de tallas hermanas, mínimo fijo, histórico de esa talla, plantilla de curva, o no estimar. Tú decides."},{"id":"h3","tipo":"encabezado","nivel":3,"texto":"3 · ¿Cómo ordena mis tallas?"},{"id":"q3","tipo":"texto","texto":"Que te enseñen un reporte con 22.5 y otro con XS a XXL."},{"id":"a3","tipo":"aviso","texto":"✅ **Sacs ordena las numéricas como números y las alfabéticas en su orden.** 22.5 va entre 22 y 23, donde debe ir. 🥾"},{"id":"h4","tipo":"encabezado","nivel":3,"texto":"4 · En el pico, ¿cuántas ventas por minuto ha aguantado?"},{"id":"q4","tipo":"texto","texto":"Con un cliente real y con nombre. No adjetivos."},{"id":"a4","tipo":"aviso","texto":"✅ **Cuatro ventas por minuto en hora pico, 150,000 transacciones sin un error.** LiveShow, merch de giras, cientos de puntos de venta a la vez."},{"id":"h5","tipo":"encabezado","nivel":3,"texto":"5 · ¿Quién limpia mi catálogo y cuánto tarda?"},{"id":"q5","tipo":"texto","texto":"Aquí es donde se mueren la mayoría de las implementaciones."},{"id":"a5","tipo":"aviso","texto":"✅ **Lo hacemos contigo en la semana uno, con alcance por escrito antes de empezar.** No te dejamos el archivo y buena suerte."},{"id":"h6","tipo":"encabezado","nivel":3,"texto":"6 · Si la prenda está en la tienda equivocada, ¿me avisa?"},{"id":"q6","tipo":"texto","texto":"Un reporte que hay que abrir no es una alerta."},{"id":"a6","tipo":"aviso","texto":"✅ **Sacs te propone el traspaso.** Ve el hueco de una tienda y el excedente de otra, y te dice qué mover. 🔁"},{"id":"h7","tipo":"encabezado","nivel":3,"texto":"7 · El sábado de Buen Fin a las 6 de la tarde, ¿quién contesta?"},{"id":"q7","tipo":"texto","texto":"Pide un nombre. No un correo de soporte."},{"id":"a7","tipo":"aviso","texto":"✅ **Yo.** La misma persona que te implementó y que conoce tu operación."},{"id":"s2","tipo":"separador"},{"id":"b1","tipo":"boton","texto":"💬 Resolver una duda por WhatsApp","align":"center","sub":"¿Alguna pregunta con más detalle? ¿O ya quieres arrancar? Por aquí es más rápido.","href":"https://wa.me/12058920417?text=Hola%20Andrea,%20tengo%20una%20duda%20sobre%20una%20de%20las%20siete%20preguntas"},{"id":"fi","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"},{"id":"pd","tipo":"texto","texto":"P.D. Guárdate esta lista. Sirve para cualquier sistema que estés viendo — y para que nadie te venda con adjetivos."}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Oportunidad 3 · El hueco de curva', 'La talla que vendió cero porque nunca estuvo', 'Tu sistema la anotó como talla muerta. Y con eso compraste la siguiente.', 'automatizado', 'simple', 'ventas',
        '[{"id":"t1","tipo":"texto","texto":"{{nombre|Hola}}, te quiero contar el error más caro de la moda."},{"id":"t2","tipo":"texto","texto":"Y lo más incómodo: casi nadie sabe que lo está cometiendo."},{"id":"s0","tipo":"separador"},{"id":"t3","tipo":"texto","texto":"La M se agotó el día 9. 📉"},{"id":"t4","tipo":"texto","texto":"Los otros cincuenta y un días vendió cero. No porque nadie la quisiera — porque no había qué vender."},{"id":"i1","tipo":"imagen","src":"https://www.sacscloud.com/email/moda/moda-hueco-curva.png","alt":"Dos gráficas: la talla M con tres ventas al inicio y sin existencia el resto, y la XXL con tres ventas repartidas","pie":"Las dos vendieron tres piezas. Solo una tiene demanda."},{"id":"t5","tipo":"texto","texto":"Llega el momento de comprar."},{"id":"t6","tipo":"texto","texto":"El reporte dice: la M vendió 3. La XXL vendió 3."},{"id":"t7","tipo":"texto","texto":"**Parecen el mismo dato. Son lo contrario.**"},{"id":"t8","tipo":"texto","texto":"Una se acabó en la primera semana. La otra estuvo colgada dos meses y nadie la tocó."},{"id":"t9","tipo":"texto","texto":"¿Y qué haces? Compras las dos igual.\n\nY la temporada siguiente vuelves a quedarte sin M. 🔁"},{"id":"s1","tipo":"separador"},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Cómo lo resolvemos"},{"id":"t10","tipo":"texto","texto":"Sacs detecta que la talla estuvo agotada y estima lo que **habría** vendido."},{"id":"t11","tipo":"texto","texto":"Y no te impone el método. Eliges uno de cinco:"},{"id":"l1","tipo":"lista","items":["⚖️ **Promedio de tallas hermanas.** Rellena el hueco con el promedio de lo que sí vendió. Es el recomendado.","🔢 **Mínimo fijo por talla.** Trae al menos una cantidad fija. Tú defines cuántas.","📈 **Histórico de esa talla.** La estima con su propia venta en un periodo más largo. Ideal si estuvo agotada ahora pero antes vendía.","📐 **Plantilla de curva por categoría.** Usa la curva objetivo que tú definiste: S:1, M:3, L:3, XL:2.","🚫 **No estimar.** Solo marca el hueco y tú decides. Conservador."]},{"id":"a1","tipo":"aviso","texto":"Y un detalle que dice más que los cinco juntos: si esa categoría no tiene curva definida, el cuarto método **cae solo al promedio** en vez de tronar. Eso no se le ocurre a quien no ha vivido una temporada de compras."},{"id":"i2","tipo":"imagen","src":"https://www.sacscloud.com/email/moda/moda-atelier.jpg","alt":"Mesa de taller con maniquí, muestras de tela, cinta métrica y papel de patrón","pie":"La decisión de compra empieza aquí, meses antes de que la prenda llegue al piso."},{"id":"b1","tipo":"boton","texto":"💬 Pruébalo con un estilo tuyo","align":"center","sub":"Tráeme el estilo que se te descabaló más rápido y te enseño cuánto cambia la compra con cada método.","href":"https://wa.me/12058920417?text=Hola%20Andrea,%20quiero%20ver%20el%20hueco%20de%20curva%20con%20un%20estilo%20de%20mi%20temporada%20pasada"},{"id":"fi","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"},{"id":"pd","tipo":"texto","texto":"P.D. Si quieres jugar con los números antes de hablar conmigo, arma tu propia curva aquí: sacscloud.com/campana/curva-de-tallas"}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Oportunidad 4 · No hay que comprar, hay que mover', 'No hay que comprar. Hay que mover.', 'Polanco no tiene M ni L. En la cadena hay cinco y siete.', 'automatizado', 'simple', 'ventas',
        '[{"id":"t1","tipo":"texto","texto":"{{nombre|Hola}}, ayer te conté cómo se compra mal."},{"id":"t2","tipo":"texto","texto":"Hoy algo peor: **comprar lo que ya tienes.** 💸"},{"id":"s0","tipo":"separador"},{"id":"t3","tipo":"texto","texto":"Imagina un martes cualquiera."},{"id":"t4","tipo":"texto","texto":"En Polanco falta la M. Y falta la L. Son justo las dos que más vende esa tienda."},{"id":"t5","tipo":"texto","texto":"La encargada las pide en la siguiente orden de compra. Y hace bien — desde donde ella ve, no hay."},{"id":"i1","tipo":"imagen","src":"https://www.sacscloud.com/email/moda/moda-multitienda.png","alt":"Matriz de una prenda en cuatro tiendas: Polanco en cero en M y L, con existencia en las otras","pie":"Una prenda, cuatro tiendas. La decisión está en el renglón de abajo."},{"id":"t6","tipo":"texto","texto":"Pero mira el renglón de abajo."},{"id":"t7","tipo":"texto","texto":"**En la cadena hay cinco M y siete L.**"},{"id":"t8","tipo":"texto","texto":"Están en Satélite y en Perisur. Colgadas. Envejeciendo. Camino a la rebaja de fin de temporada."},{"id":"t9","tipo":"texto","texto":"¿Cuánto cuesta esa compra? El doble: pagas mercancía nueva y rematas la vieja."},{"id":"s1","tipo":"separador"},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Lo que cambia cuando el sistema ve todas tus tiendas"},{"id":"l1","tipo":"lista","items":["👗 **La clienta que pide la M.** No hay aquí, hay tres en la otra tienda, y se aparta desde el mostrador antes de que se vaya. Hoy esa venta se pierde — y no aparece en ningún reporte, porque una venta que no ocurrió no se registra.","🔁 **El traspaso se propone solo.** El sistema ve el hueco y el excedente, y te dice qué mover. Con su documento, no en la camioneta del gerente.","🛒 **La compra se hace sobre la cadena.** Primero se acomoda lo que ya pagaste. Lo que falte después, eso sí se compra."]},{"id":"i2","tipo":"imagen","src":"https://www.sacscloud.com/email/moda/moda-cedis.jpg","alt":"Nave de distribución de moda con estanterías ordenadas","pie":"Mover no es un trámite: es la diferencia entre vender a precio y rematar."},{"id":"t10","tipo":"texto","texto":"Un sistema de una sola tienda no puede hacer esto aunque quiera.\n\nNo tiene con qué comparar."},{"id":"b1","tipo":"boton","texto":"💬 ¿Cuántas tiendas tienes?","align":"center","sub":"Dime cuántas son y te enseño cómo se vería tu tablero de traspasos.","href":"https://wa.me/12058920417?text=Hola%20Andrea,%20quiero%20ver%20como%20funcionaria%20el%20traspaso%20entre%20mis%20tiendas"},{"id":"fi","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"},{"id":"pd","tipo":"texto","texto":"P.D. Un dato que casi nadie conoce a tiempo: cada traspaso de más de 30 kilómetros necesita CFDI de traslado con Carta Porte 3.1, y la multa va de $17,020 a $51,060. Si hoy mueves mercancía sin papel, el sistema debería generarte ese documento solo. 📄"}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Oportunidad 5 · Las marcas que ponen el ejemplo', 'Lo que Bershka puso en su tienda de Madero', 'Espejos que sugieren outfits. Y lo que hay detrás para que funcionen.', 'automatizado', 'simple', 'ventas',
        '[{"id":"t1","tipo":"texto","texto":"{{nombre|Hola}}, hoy no te hablo de nosotros."},{"id":"t2","tipo":"texto","texto":"Te hablo de a dónde va la tienda física. 🏬"},{"id":"s0","tipo":"separador"},{"id":"i1","tipo":"imagen","src":"https://www.sacscloud.com/email/moda/moda-wow-planta.jpg","alt":"Interior de una tienda concepto multimarca de doble altura, con columnas restauradas y escalera abierta","pie":"La tienda dejó de ser una bodega con vitrina. Ahora es el medio."},{"id":"t3","tipo":"texto","texto":"En Madrid, WOW Concept abrió en Gran Vía 18 y Serrano 52: una tienda multimarca donde el espacio físico es el contenido, no el almacén."},{"id":"t4","tipo":"texto","texto":"En Ciudad de México, Bershka hizo lo suyo en Francisco I. Madero. Mil trescientos cuarenta metros cuadrados, tres plantas."},{"id":"t5","tipo":"texto","texto":"Y adentro, tres cosas que vale la pena mirar con calma:"},{"id":"m1","tipo":"metricas","items":[{"cifra":"−15%","texto":"devoluciones con realidad aumentada"},{"cifra":"+20%","texto":"venta adicional con espejos inteligentes"},{"cifra":"−30%","texto":"tiempo de espera en caja"}]},{"id":"i2","tipo":"imagen","src":"https://www.sacscloud.com/email/moda/moda-wow-espejo.jpg","alt":"Espejo inteligente empotrado en el muro de una boutique premium","pie":"El espejo sugiere combinaciones. Pero solo puede sugerir lo que existe."},{"id":"t6","tipo":"texto","texto":"Ahora la parte que nadie cuenta."},{"id":"t7","tipo":"texto","texto":"**Un espejo que sugiere outfits no sirve de nada si el catálogo está sucio.** 🪞"},{"id":"t8","tipo":"texto","texto":"Si la misma prenda está dada de alta tres veces, el espejo la sugiere tres veces.\n\nSi no sabe qué talla queda en ESA tienda, sugiere una talla que no puedes darle.\n\nSi la foto no es consistente, la pantalla se ve peor que el rack."},{"id":"s1","tipo":"separador"},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Lo que hay debajo del wow"},{"id":"t9","tipo":"texto","texto":"Toda esa experiencia se para sobre tres cosas nada glamorosas:"},{"id":"l1","tipo":"lista","items":["🧵 **Un catálogo limpio,** con talla y color como una sola prenda.","🏬 **Existencia real por tienda,** no un total de la cadena.","🌐 **Un solo inventario** para el piso, la línea y el WhatsApp."]},{"id":"t10","tipo":"texto","texto":"Eso es exactamente lo que hacemos.\n\nNo somos los que ponen el espejo. Somos los que hacen que el espejo tenga algo cierto que decir."},{"id":"i3","tipo":"imagen","src":"https://www.sacscloud.com/email/moda/moda-wow-vitrina.jpg","alt":"Fachada iluminada de una tienda insignia de moda por la noche","pie":"Para llegar aquí no se empieza por la pantalla. Se empieza por el catálogo."},{"id":"b1","tipo":"boton","texto":"💬 ¿Cómo se ve tu catálogo hoy?","align":"center","sub":"Te digo con honestidad qué te falta antes de pensar en pantallas.","href":"https://wa.me/12058920417?text=Hola%20Andrea,%20quiero%20saber%20que%20tan%20listo%20esta%20mi%20catalogo%20para%20este%20tipo%20de%20experiencia"},{"id":"fi","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"},{"id":"pd","tipo":"texto","texto":"P.D. Los datos de Bershka salieron de una investigación que publicamos en el blog. Si quieres el artículo completo, te lo mando."}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Oportunidad 6 · El caso y la parte fea', '150 mil ventas sin un error (y la parte fea)', 'El caso que se parece a tu temporada alta, incluido lo que costó.', 'automatizado', 'simple', 'ventas',
        '[{"id":"t1","tipo":"texto","texto":"{{nombre|Hola}}, todos los proveedores te cuentan la primera mitad de sus casos."},{"id":"t2","tipo":"texto","texto":"Yo te voy a contar las dos."},{"id":"s0","tipo":"separador"},{"id":"c1","tipo":"cita","texto":"En un concierto perdimos 20% de ventas en dos horas porque el sistema colapsó. Con SACS eso no vuelve a pasar.","autor":"Mariana López · Directora de Operaciones, LiveShow"},{"id":"t3","tipo":"texto","texto":"LiveShow vende merch de giras en México. Playeras y hoodies con tallas, en cientos de puntos de venta a la vez."},{"id":"t4","tipo":"texto","texto":"Shakira. Metallica. Karol G. Lady Gaga. 🎤"},{"id":"m1","tipo":"metricas","items":[{"cifra":"150,000+","texto":"transacciones sin un error"},{"cifra":"4 / min","texto":"ventas en hora pico"},{"cifra":"3,800","texto":"ventas en 8 horas, Foro Sol"}]},{"id":"t5","tipo":"texto","texto":"Tú no vendes en estadios."},{"id":"t6","tipo":"texto","texto":"Pero tu sábado de Buen Fin es exactamente eso, a menor escala: cola larga, gente que se va si tarda, y cero posibilidad de resurtir."},{"id":"t7","tipo":"texto","texto":"En un evento, el inventario que llegó es todo el que habrá.\n\nEn tu temporada, la corrida que compraste es toda la que habrá."},{"id":"a1","tipo":"aviso","texto":"Y el dato que a mí me quita el sueño: en México **se devuelve el 35% de lo que se vende de moda en línea** — la tasa más alta de todas las categorías. Un tercio de esas devoluciones es por talla equivocada. Eso no es paquetería. Es no saber qué talla tienes, y dónde."},{"id":"s1","tipo":"separador"},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"Ahora la segunda mitad"},{"id":"i1","tipo":"imagen","src":"https://www.sacscloud.com/email/moda/moda-botas.jpg","alt":"Par de botas western de piel labrada sobre fondo hueso","pie":"Botas: medias tallas más ancho. La corrida más difícil que existe en moda."},{"id":"t8","tipo":"texto","texto":"Trabajamos con marcas de botas western. Medias tallas —22.5, 23.5, 24.5— más el ancho."},{"id":"t9","tipo":"texto","texto":"Y antes de que el sistema sugiriera una sola compra, hubo semanas de trabajo que nadie presume:"},{"id":"l1","tipo":"lista","items":["🧹 **Limpiar el catálogo.** Prendas duplicadas, tallas escritas de tres formas, costos que nadie revisó en años. Si tu catálogo está sucio, esas semanas van a existir.","🙋 **El equipo se resiste.** Siempre hay alguien en piso con años en su método que la primera semana va a decir que antes era más rápido. Tiene razón la primera semana. Deja de tenerla en la tercera.","📦 **No se migra todo.** Catálogo activo, existencias, clientes y apartados abiertos, sí. Años de histórico del sistema viejo y prendas muertas, no. Arrastrar basura es la forma más común de estrenar un sistema que ya nace sucio."]},{"id":"i2","tipo":"imagen","src":"https://www.sacscloud.com/email/moda/moda-etiqueta.jpg","alt":"Macro de etiqueta de cuidado y etiqueta de precio sobre una prenda de punto","pie":"El trabajo invisible: que cada prenda esté bien dada de alta, una sola vez."},{"id":"t10","tipo":"texto","texto":"Te lo digo antes y no después."},{"id":"t11","tipo":"texto","texto":"Después de firmar se llama sorpresa. Antes de firmar se llama plan. 🤝"},{"id":"b1","tipo":"boton","texto":"💬 Pregúntame lo incómodo","align":"center","sub":"Cuánto tarda, qué necesita tu equipo, qué puede salir mal. Te contesto de frente.","href":"https://wa.me/12058920417?text=Hola%20Andrea,%20quiero%20preguntarte%20algo%20sobre%20la%20implementacion"},{"id":"fi","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"},{"id":"pd","tipo":"texto","texto":"P.D. Y lo que nadie pregunta hasta que es tarde: el sábado de temporada a las 6 de la tarde no le escribes a un buzón. Me escribes a mí, la misma persona que te implementó."}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Oportunidad 7 · El probador virtual', 'En tu tienda caben 200 prendas', 'En tu catálogo hay 2,000. La pantalla enseña las dos mil.', 'automatizado', 'simple', 'ventas',
        '[{"id":"t1","tipo":"texto","texto":"{{nombre|Hola}}, los correos anteriores fueron de lo que no se ve."},{"id":"t2","tipo":"texto","texto":"Cómo se compra. Cómo se mueve. El trabajo de abajo."},{"id":"t3","tipo":"texto","texto":"Este es de lo que sí se ve. ✨"},{"id":"i1","tipo":"imagen","src":"https://www.sacscloud.com/email/moda/moda-probador.jpg","alt":"Pantalla interactiva de pie en una boutique, mostrando la retícula del catálogo","pie":"El probador virtual se alimenta de tu catálogo. No hay que cargar nada aparte."},{"id":"t4","tipo":"texto","texto":"Una pantalla en el piso. Tu clienta prueba prendas, arma combinaciones, cambia colores y tallas."},{"id":"t5","tipo":"texto","texto":"Sin buscar en el rack. Sin hacer fila."},{"id":"s0","tipo":"separador"},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"En tu tienda caben doscientas prendas. En tu catálogo hay dos mil."},{"id":"t6","tipo":"texto","texto":"Esa es toda la idea."},{"id":"t7","tipo":"texto","texto":"El rack solo puede enseñar lo que cupo en el piso de esa tienda."},{"id":"t8","tipo":"texto","texto":"**La pantalla enseña tu catálogo completo.** Incluido lo que está en la otra sucursal."},{"id":"t9","tipo":"texto","texto":"Es el mismo argumento del correo de la matriz, pero del lado de la clienta:\n\nla prenda que le iba a encantar existe. Solo que no está colgada frente a ella. 👗"},{"id":"i2","tipo":"imagen","src":"https://www.sacscloud.com/email/moda/moda-rack-color.jpg","alt":"Un riel largo con prendas ordenadas en degradado de color, de hueso a carbón","pie":"Lo que cabe en un riel. Tu catálogo es diez veces esto."},{"id":"s1","tipo":"separador"},{"id":"l1","tipo":"lista","items":["🗂️ **Se alimenta de tu catálogo.** El mismo que ya vive en el sistema. Nadie sube fotos aparte ni mantiene dos inventarios.","✅ **Sigue la existencia real.** Si una talla se acabó, deja de aparecer. Tu clienta nunca se ilusiona con algo que no puedes darle.","🛍️ **Se prueba más de lo que se probaría.** Sin fila, sin cargar seis prendas al probador, sin pedirle a nadie que vaya por la otra talla."]},{"id":"t10","tipo":"texto","texto":"Y recuerda el dato de Bershka: los espejos inteligentes subieron su venta adicional **20%.**"},{"id":"b1","tipo":"boton","texto":"💬 Quiero verlo funcionando","align":"center","sub":"Te lo enseño en vivo, con prendas reales.","href":"https://wa.me/12058920417?text=Hola%20Andrea,%20quiero%20ver%20el%20probador%20virtual"},{"id":"fi","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"},{"id":"pd","tipo":"texto","texto":"P.D. Si tu catálogo hoy no tiene fotos consistentes, esto no se ve bien. Es otra razón para hacer bien la semana uno: la misma limpieza que hace que la compra funcione es la que hace que la vitrina se vea. 📸"}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Oportunidad 8 · La decisión', 'Dos fechas y una resta', 'Nada de urgencia inventada. Solo el calendario, tal como está.', 'automatizado', 'simple', 'ventas',
        '[{"id":"t1","tipo":"texto","texto":"{{nombre|Hola}}, sin adornos: dos fechas y una resta."},{"id":"s0","tipo":"separador"},{"id":"h1","tipo":"encabezado","nivel":2,"texto":"La primera ya está corriendo"},{"id":"t2","tipo":"texto","texto":"Desde enero, la ropa que entra sin tratado paga **35% de arancel.**"},{"id":"t3","tipo":"texto","texto":"No el 50% que titularon los medios — ese es el techo de otras fracciones. Con IVA, tu multiplicador sobre valor en aduana queda en 1.57."},{"id":"t4","tipo":"texto","texto":"Y las tres rutas baratas se cerraron: IMMEX para prenda terminada, depósito fiscal y recinto fiscalizado."},{"id":"t5","tipo":"texto","texto":"Por primera vez en años, **comprar bien pesa más que comprar barato.** 📊"},{"id":"h2","tipo":"encabezado","nivel":2,"texto":"La segunda es Intermoda de enero"},{"id":"t6","tipo":"texto","texto":"Cuatro días en Expo Guadalajara para comprometer seis meses de capital."},{"id":"t7","tipo":"texto","texto":"La única pregunta que importa: ¿vas a llegar ahí con el sell-through por estilo y por tienda de esta temporada?\n\n¿O con lo que te acuerdes?"},{"id":"i1","tipo":"imagen","src":"https://www.sacscloud.com/email/moda/moda-atelier.jpg","alt":"Mesa de taller con muestras de tela, cinta métrica y papel de patrón","pie":"En enero se decide la temporada. Con datos o con memoria."},{"id":"s1","tipo":"separador"},{"id":"h3","tipo":"encabezado","nivel":2,"texto":"Y ahora la resta"},{"id":"t8","tipo":"texto","texto":"El Buen Fin cae a mediados de noviembre."},{"id":"t9","tipo":"texto","texto":"La implementación son 4 semanas. El rodaje, 2 más. Súmale una semana entre firma y arranque real, porque siempre existe."},{"id":"t10","tipo":"texto","texto":"Para llegar a tu temporada fuerte con el sistema **ya rodado** —no estrenándolo— la decisión tiene que estar tomada alrededor del 1 de octubre."},{"id":"t11","tipo":"texto","texto":"No es una fecha de venta. Es una resta. 🗓️"},{"id":"s2","tipo":"separador"},{"id":"h4","tipo":"encabezado","nivel":2,"texto":"Dos caminos, los dos buenos"},{"id":"l1","tipo":"lista","items":["🚀 **Arrancamos ahora.** Me lo confirmas esta semana, bloqueo el calendario y la semana 1 empieza de inmediato. Entras al Buen Fin con la operación corriendo.","📅 **Lo movemos a después de temporada.** Con toda la lógica: no se arranca en pleno pico. Retomamos en cuanto baje, sin volver a empezar de cero."]},{"id":"t12","tipo":"texto","texto":"Dime cuál y me organizo contigo."},{"id":"b1","tipo":"boton","texto":"💬 Decidir por WhatsApp","align":"center","sub":"Un mensaje y lo resolvemos. Sin junta.","href":"https://wa.me/12058920417?text=Hola%20Andrea,%20ya%20lo%20platicamos%20internamente%20y%20quiero%20decirte%20como%20vamos"},{"id":"fi","tipo":"firma","nombre":"Andrea Gutiérrez Araujo","puesto":"Tu consultora en Sacs","foto_url":"https://www.sacscloud.com/images/andrea-consultora.jpg"},{"id":"pd","tipo":"texto","texto":"P.D. Si el número no cabe en el presupuesto de este año, dímelo directo. Hay una fase 1 más chica que resuelve el piso de venta y deja la compra para después. Prefiero un proyecto que arranca a uno completo que se queda en revisión."}]'::jsonb, true);

update crm_secuencias set corte_dias = 14,
  descripcion = 'Doce días de credibilidad para marcas de moda que ya vieron la demo y ya tienen cotización. Ocho correos: las diez cosas que un genérico no hace, las siete preguntas con nuestra respuesta, el hueco de curva, el traspaso entre tiendas, las marcas que ponen el ejemplo, el caso de LiveShow con su parte fea, el probador virtual y el cierre por calendario. Todos con botón de WhatsApp.'
where nombre = 'Oportunidad · Moda multitienda';

insert into crm_secuencia_pasos (secuencia_id, orden, dia, canal, email_template_id, activo)
select s.id, p.orden, p.dia, 'correo', t.id, true
from crm_secuencias s
cross join (values
  (1, 1, 'Oportunidad 1 · Diez cosas que un genérico no hace'),
  (2, 3, 'Oportunidad 2 · Las 7 preguntas'),
  (3, 5, 'Oportunidad 3 · El hueco de curva'),
  (4, 6, 'Oportunidad 4 · No hay que comprar, hay que mover'),
  (5, 8, 'Oportunidad 5 · Las marcas que ponen el ejemplo'),
  (6, 9, 'Oportunidad 6 · El caso y la parte fea'),
  (7, 11, 'Oportunidad 7 · El probador virtual'),
  (8, 12, 'Oportunidad 8 · La decisión')
) as p(orden, dia, plantilla)
join email_templates t on t.nombre = p.plantilla
where s.nombre = 'Oportunidad · Moda multitienda';
commit;
